begin;
select plan(48);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data) values
('00000000-0000-0000-0000-000000000000','10000000-0000-4000-8000-000000000001','authenticated','authenticated','community-author@ritmo.test','',now(),now(),now(),'{}','{}'),
('00000000-0000-0000-0000-000000000000','20000000-0000-4000-8000-000000000002','authenticated','authenticated','community-reader@ritmo.test','',now(),now(),now(),'{}','{}'),
('00000000-0000-0000-0000-000000000000','30000000-0000-4000-8000-000000000003','authenticated','authenticated','community-moderator@ritmo.test','',now(),now(),now(),'{}','{}');
insert into public.public_creator_profiles(id,user_id,handle,display_name) values ('11000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','autor-ritmo','Autor Ritmo');
insert into public.community_staff_roles(user_id,role) values ('30000000-0000-4000-8000-000000000003','moderator');
insert into public.creative_template_catalog(id,template_key,version,origin,title,summary,creative_type,format,platform,objective,template_json) values ('14000000-0000-4000-8000-000000000001','official:short-video',1,'official','Vídeo oficial curto','Modelo oficial para adaptação segura.','short_video','reel','instagram','educação','{"objective":"Educar"}');
insert into public.content_plans(id,user_id,platform,title,objective,format,status) values ('12000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','instagram','Roteiro confirmado','Educar','reel','scheduled');
insert into public.content_versions(id,user_id,content_plan_id,version,payload,approval_idempotency_key,approval_request_hash) values ('13000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001',1,'{"objective":"Ensinar recuperação segura.","caption":"Salve para praticar.","private_context":"segredo"}','approval:community-source','hash');
select has_table('public','community_posts','community posts table exists');
select has_view('public','community_library','safe public view exists');
select is((select count(*)::integer from public.community_feature_flags where enabled),0,'all server-side flags default off');
select is((select count(*)::integer from public.community_library),0,'read flag fails public view closed');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Publicação bloqueada por feature flag','Resumo suficientemente longo enquanto submissões estão desligadas.',null,'{}','{}','short_video','reel','instagram','educação',true,true,null,'disabled:key-01')$$,'55000','community submissions disabled','submissions fail closed by default');
select throws_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',1,null,'Quero adaptar este roteiro oficial.','official:disabled-01')$$,'55000','community adaptation disabled','official adaptation fails closed by default');
reset role;
update public.community_feature_flags set enabled=true,updated_at=now();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Recuperação simples depois da corrida','Um roteiro curto e cuidadoso para orientar a recuperação pós-treino.','Adapte os exemplos.',array['fitness'],array['vídeo curto'],'short_video','reel','instagram','educação',true,true,null,'submit:key-0001')$$,'author submits approved server-side version');
select lives_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Recuperação simples depois da corrida','Um roteiro curto e cuidadoso para orientar a recuperação pós-treino.','Adapte os exemplos.',array['fitness'],array['vídeo curto'],'short_video','reel','instagram','educação',true,true,null,'submit:key-0001')$$,'submission retry replays safely');
select is((select count(*)::integer from public.community_submissions),1,'submission retry creates no duplicate');
select throws_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Título diferente com a mesma chave','Um resumo diferente e longo reutilizando a chave anterior.',null,'{}','{}','short_video','reel','instagram','educação',true,true,null,'submit:key-0001')$$,'22023','idempotency key reused with different request','submission key cannot change request');
select is((select snapshot from public.community_submissions limit 1),(select payload - 'private_context' from public.content_versions where id='13000000-0000-4000-8000-000000000001'),'snapshot copied server-side');
select ok(not ((select snapshot from public.community_submissions limit 1) ? 'private_context'),'snapshot excludes non-public fields');
select is((select editorial_status::text from public.community_submissions limit 1),'pending','submission starts pending');
select throws_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Título válido para envio','Resumo suficientemente longo para ser aceito pela plataforma.',null,'{}','{}','short_video','reel','instagram','educação',false,true,null,'submit:key-rights')$$,'22023','rights and adaptation license are required','rights consent mandatory');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Tentativa com conteúdo de terceiro','Resumo longo tentando publicar conteúdo de outro usuário.',null,'{}','{}','short_video','reel','instagram','educação',true,true,null,'submit:key-foreign')$$,'P0002','approved content version not found','foreign source rejected');
select is((select count(*)::integer from public.community_submissions),0,'reader cannot see author submission');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select throws_ok(format('select public.moderate_community_submission(%L,''approved'',null)',(select id from public.community_submissions limit 1)),'42501','moderator role required','author cannot self approve');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select lives_ok(format('select public.moderate_community_submission(%L,''approved'',null)',(select id from public.community_submissions limit 1)),'moderator approves');
select is((select count(*)::integer from public.creative_template_catalog where origin='community'),1,'approval creates template');
select lives_ok(format('select public.moderate_community_submission(%L,''approved'',null)',(select id from public.community_submissions limit 1)),'repeated approval idempotent');
select is((select count(*)::integer from public.creative_template_catalog where origin='community'),1,'no duplicate template');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is((select count(*)::integer from public.community_library),1,'anonymous reads approved post');
select is((select count(*)::integer from public.public_creator_directory),1,'anonymous reads safe public creator profile');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select ok(public.set_community_like((select id from public.community_library limit 1),true),'reader sets like');
select ok(public.set_community_like((select id from public.community_library limit 1),true),'like retry preserves desired state');
select is((select count(*)::integer from public.community_post_likes),1,'like retry creates no duplicate');
select ok(not public.set_community_like((select id from public.community_library limit 1),false),'reader removes like deterministically');
select ok(public.set_community_save((select id from public.community_library limit 1),true),'reader sets save');
select ok(public.set_community_save((select id from public.community_library limit 1),true),'save retry preserves desired state');
select lives_ok($$select public.report_community_post((select id from public.community_library limit 1),'other','Revisar esta publicação.')$$,'reader reports once idempotently');
select throws_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',2,null,'Quero adaptar este roteiro oficial.','official:wrong-version')$$,'P0002','approved template version not found','wrong template version is rejected atomically');
select throws_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',1,null,'curto','official:short-brief')$$,'22023','invalid adaptation brief','short adaptation brief is rejected');
select lives_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',1,null,'Quero adaptar este roteiro oficial.','official:adapt-01')$$,'official adaptation starts');
select is((select payload#>>'{request,adaptation_brief}' from public.ai_jobs where kind='content.adapt'),'Quero adaptar este roteiro oficial.','validated brief is queued atomically');
select lives_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',1,null,'Quero adaptar este roteiro oficial.','official:adapt-01')$$,'official adaptation retry replays');
select is((select count(*)::integer from public.community_reuse_provenance where source_post_id is null),1,'official provenance has no community post');
set local role service_role;
select lives_ok($$select public.complete_community_adaptation((select ai_job_id from public.community_reuse_provenance where source_post_id is null),'{"caption":"Resultado oficial adaptado"}')$$,'worker completes official adaptation');
select lives_ok($$select public.complete_community_adaptation((select ai_job_id from public.community_reuse_provenance where source_post_id is null),'{"caption":"Resultado oficial adaptado"}')$$,'worker completion retry replays');
select is((select count(*)::integer from public.content_versions where user_id='20000000-0000-4000-8000-000000000002'),1,'worker creates one result version');
select throws_ok($$select public.complete_community_adaptation((select ai_job_id from public.community_reuse_provenance where source_post_id is null),'{"caption":"Resultado divergente"}')$$,'22023','adaptation job replayed with different result','worker rejects divergent completion replay');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.start_template_adaptation((select id from public.public_template_catalog where origin='community'),(select version from public.public_template_catalog where origin='community'),(select id from public.community_library limit 1),'Adapte ao meu público mantendo a estrutura.','community:adapt-01')$$,'community adaptation starts');
select lives_ok($$select public.start_template_adaptation((select id from public.public_template_catalog where origin='community'),(select version from public.public_template_catalog where origin='community'),(select id from public.community_library limit 1),'Adapte ao meu público mantendo a estrutura.','community:adapt-01')$$,'community adaptation retry replays');
select is((select count(*)::integer from public.community_reuse_provenance),2,'official and community provenance recorded once each');
select throws_ok($$select public.start_template_adaptation('14000000-0000-4000-8000-000000000001',1,(select id from public.community_library limit 1),'Quero adaptar este roteiro oficial.','official:adapt-01')$$,'22023','idempotency key reused with different source','adaptation key cannot change source');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.withdraw_community_post((select id from public.community_posts limit 1))$$,'author withdraws');
select is((select count(*)::integer from public.community_library),0,'withdrawal removes public listing');
set local role service_role;
select throws_ok($$insert into public.creative_template_catalog(template_key,version,origin,title,summary,creative_type,format,platform,objective,template_json) values ('invalid:malicious',1,'official','Inválido','Tipo não suportado','malicious_type','reel','instagram','teste','{}')$$,'23514','new row for relation "creative_template_catalog" violates check constraint "creative_template_catalog_creative_type_canonical"','catalog rejects unsupported creative type');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.submit_community_content('13000000-0000-4000-8000-000000000001','Tipo criativo malicioso','Resumo suficientemente longo para testar tipo inválido.',null,'{}','{}','malicious_type','reel','instagram','educação',true,true,null,'submit:invalid-type')$$,'23514','new row for relation "community_submissions" violates check constraint "community_submissions_creative_type_canonical"','submission rejects unsupported creative type');
select * from finish();
rollback;
